#define DECLARE_PRIVATE_VARSINFO(ClassObject,DimV) \  typedef ClassObject ClassObject_; \  static ClassObject s_private; \  static SVarInfo s_privateVarInfo[DimV]; \  static DWORD s_kprivateVarInfo = 0; \  static SVarInfo::tFlagType_ s_defPrivateFlag = SVarInfo::efEmpty;template<typename C>void InitPrivateInfo( eHcdVType type, tHcdVarSizeType_ offset, tHcdVarSizeType_ size, LPCSTR pszVarName, LPCSTR pszLgxName ){  if( s_kprivateVarInfo == _countof(s_privateVarInfo) )    throw 1;  SVarInfo * pV = &(s_privateVarInfo[s_kprivateVarInfo++]);  pV->shift = offset;  pV->pszName = pszVarName;  pV->pszLgxParamName = pszLgxName;  pV->evtType = type;  pV->size = size;  if( sizeof(C) < (offset+size) )    throw 2;  pV->flags |= s_defPrivateFlag;}template<typename C>void InitPrivateInfo( eHcdVType type, tHcdVarSizeType_ offset, tHcdVarSizeType_ size, LPCSTR pszVarName, LPCSTR pszLgxName, LPCSTR penumVals ){  if( s_kprivateVarInfo == _countof(s_privateVarInfo) )    throw 1;  SVarInfo * pV = &(s_privateVarInfo[s_kprivateVarInfo++]);  pV->shift = offset;  pV->pszName = pszVarName;  pV->pszLgxParamName = pszLgxName;  pV->evtType = type;  pV->size = size;  if( sizeof(C) < (offset+size) )    throw 2;  pV->flags |= s_defPrivateFlag;  pV->flags |= SVarInfo::efEnum;  pV->pszEnumVals = penumVals;}#undef PrivateAnalog32#define PrivateAnalog32(Var,Lgx) \  InitPrivateInfo<ClassObject_>( ehtAnalog32, offsetof(ClassObject_, Var), sizeof(((ClassObject_*)0)->Var), #Var, Lgx ); #undef PrivateAnalog32Savebale#define PrivateAnalog32Savebale(Var,Lgx) \  s_defPrivateFlag |= SVarInfo::efSaveInState;\  InitPrivateInfo<ClassObject_>( ehtAnalog32, offsetof(ClassObject_, Var), sizeof(((ClassObject_*)0)->Var), #Var, Lgx );\  s_defPrivateFlag &= ~SVarInfo::efSaveInState;#undef PrivateDigital32#define PrivateDigital32(Var,Lgx) \  InitPrivateInfo<ClassObject_>( ehtDigital32, offsetof(ClassObject_, Var), sizeof(((ClassObject_*)0)->Var), #Var, Lgx ); #undef PrivateDigital32Savebale#define PrivateDigital32Savebale(Var,Lgx) \  s_defPrivateFlag |= SVarInfo::efSaveInState;\  InitPrivateInfo<ClassObject_>( ehtDigital32, offsetof(ClassObject_, Var), sizeof(((ClassObject_*)0)->Var), #Var, Lgx );\  s_defPrivateFlag &= ~SVarInfo::efSaveInState;#undef PrivateBool#define PrivateBool(Var,Lgx) \  InitPrivateInfo<ClassObject_>( ehtBool, offsetof(ClassObject_, Var), sizeof(((ClassObject_*)0)->Var), #Var, Lgx ); #undef PrivateBoolSavebale#define PrivateBoolSavebale(Var,Lgx) \  s_defPrivateFlag |= SVarInfo::efSaveInState;\  InitPrivateInfo<ClassObject_>( ehtBool, offsetof(ClassObject_, Var), sizeof(((ClassObject_*)0)->Var), #Var, Lgx );\  s_defPrivateFlag &= ~SVarInfo::efSaveInState;#undef PrivatePoint2String#define PrivatePoint2String(Var,Lgx) \  InitPrivateInfo<ClassObject_>( ehtDynStr, offsetof(ClassObject_, Var), sizeof(((ClassObject_*)0)->Var), #Var, Lgx ); #undef PrivateEnum#define PrivateEnum(Var,Lgx,...) \  InitPrivateInfo<ClassObject_>( ehtEnum, offsetof(ClassObject_, Var), sizeof(((ClassObject_*)0)->Var), #Var, Lgx, #__VA_ARGS__ ); //////////////////////////////////////////////////////////////////////////#define DECLARE_SHARED_VARSINFO(ClassObject,DimV) \  typedef ClassObject ClassObjectShared_; \  static ClassObject s_shared; \  static SVarInfo s_sharedVarInfo[DimV]; \  static DWORD s_ksharedVarInfo = 0;\  static SVarInfo::tFlagType_ s_defSharedFlag = SVarInfo::efEmpty;